    // Last bus from B departs not later than 11:59 PM = 23*60+59 = 1439 minutes

    int firstBusB = 5 * 60; // 05:00 = 300 minutes
    int lastBusB = 23 * 60 + 59; // 23:59 = 1439 minutes

    // Simion is on the road from simionDeparture to simionArrival
    // A bus from B that departs at time t will be on the road from t to t + tb
    // Simion meets this bus if their time intervals overlap (strictly, not at endpoints)
    // Simion's interval: [simionDeparture, simionArrival]
    // Bus's interval: [t, t + tb]
    // They meet if: t < simionArrival AND t + tb > simionDeparture
    // i.e., t < simionArrival AND t > simionDeparture - tb
    // So: simionDeparture - tb < t < simionArrival

    // But we also need to make sure the bus actually exists (departs between firstBusB and lastBusB)
    // And we should not count encounters at start and finish cities.
    // The problem says: "Simion doesn't count the buses he meet at the start and finish."
    // This means if the bus meets Simion exactly at simionDeparture (city A) or simionArrival (city B), don't count it.
    // Meeting at city A: bus arrives at A at time t + tb = simionDeparture, so t = simionDeparture - tb
    // Meeting at city B: bus departs from B at time t = simionArrival, so t = simionArrival

    // So we need: t > simionDeparture - tb AND t < simionArrival
    // Combined with bus existence: firstBusB <= t <= lastBusB
    // And t must be a valid departure time: t = firstBusB + k*b for some integer k >= 0

    int count = 0;

    // Find the range of valid t values
    int tMin = max(firstBusB, simionDeparture - tb + 1); // t > simionDeparture - tb means t >= simionDeparture - tb + 1
    int tMax = min(lastBusB, simionArrival - 1); // t < simionArrival means t <= simionArrival - 1

    if (tMin > tMax) {
        cout << 0 << endl;
        return 0;
    }

    // Find the first valid t >= tMin that is congruent to firstBusB mod b
    // t = firstBusB + k*b
    // We need firstBusB + k*b >= tMin
    // k >= (tMin - firstBusB) / b

    int kMin = 0;
    if (tMin > firstBusB) {
        kMin = (tMin - firstBusB + b - 1) / b; // ceiling division
    }

    int tStart = firstBusB + kMin * b;
    if (tStart < tMin) {
        tStart += b;
    }

